ttps://cdn.jsdelivr.net/npm/bootstrap@5.3.2/dist/js/bootstrap.bundle.min.js"></script>  <script src="https://cdn.jsdelivr.net/npm/sweetalert2@11"></script>    <script>      document.addEventListener("DOMContentLoaded", function() {          const urlParams = new URLSearchParams(window.location.search);          const msg = urlParams.get('msg');            // 1. Alert Sukses Login          if (msg === 'login_success') {              Swal.fire({                  icon: 'success',                  title: 'Akses Admin Diberikan',                  text: 'Selamat datang kembali, <?= $_SESSION['nama'] ?>!',                  showConfirmButton: false,                  timer: 2500,                  timerProgressBar: true,                  customClass: { popup: 'rounded-5 border-0 shadow' },                  showClass: { popup: 'animate__animated animate__fadeInDown' }              });              // Bersihkan URL parameter              window.history.replaceState({}, document.title, window.location.pathname + (urlParams.get('page') ? '?page=' + urlParams.get('page') : ''));          }            // 2. Alert Konfirmasi Logout          document.querySelector('.logout-link').addEventListener('click', function(e) {              e.preventDefault();              const href = this.getAttribute('href');                Swal.fire({                  title: 'Yakin Ingin Keluar?',                  text: "Sesi admin Anda akan diakhiri.",                  icon: 'warning',                  showCancelButton: true,                  confirmButtonColor: '#667eea',                  cancelButtonColor: '#f1f5f9',                  confirmButtonText: '<span style="color:white">Ya, Keluar</span>',                  cancelButtonText: '<span style="color:#64748b">Batal</span>',                  reverseButtons: true,                  customClass: { popup: 'rounded-5' }              }).then((result) => {                  if (result.isConfirmed) {                      window.location.href = href;                  }              });          });      });  </script>    <?php   // Tetap simpan ini untuk alert CRUD (Create, Update, Delete) di halaman switch  if(isset($_SESSION['alert'])): ?>  <script>      Swal.fire({          icon: '<?= $_SESSION['alert']['icon'] ?>',          title: '<?= $_SESSION['alert']['title'] ?>',          text: '<?= $_SESSION['alert']['text'] ?>',          timer: 2000,          showConfirmButton: false,          customClass: { popup: 'rounded-4' }      });  </script>  <?php unset($_SESSION['alert']); endif; ?>    </body>  </html>    